SELECT TableNumber,COUNT(*) AS LoadedRows
FROM stg.ABSProtectionExtended GROUP BY TableNumber ORDER BY TableNumber;
SELECT TableNumber,Metric,EstimateUnit,EstimateValue,ProportionPercent,MarginOfError95PP
FROM stg.ABSProtectionExtended WHERE Breakdown=N'National total' AND Sex=N'Persons'
ORDER BY TableNumber,EstimateCell;
SELECT TableNumber,COUNT(*) AS MissingMarginOfError
FROM stg.ABSProtectionExtended WHERE ProportionErrorStatus='Missing in source'
GROUP BY TableNumber;
